/bin/bash -lc "cat > .tmp/bgseg.py <<'PY'
import numpy as np
from scipy import ndimage as ndi
A=np.load('source_pixels.npz')['rgb'].astype(int)
for perc in ['median','q75','mode']:
 if perc=='median': B=np.median(A[36:],0)
 elif perc=='q75': B=np.quantile(A[36:],.75,axis=0)
 else: B=np.median(A[36:],0)
 print('\\n',perc)
 for f in range(12,40):
  d=np.max(abs(A[f]-B),2)>10
  d=ndi.binary_opening(d,np.ones((2,2))); d=ndi.binary_closing(d,np.ones((3,3)))
  lab,n=ndi.label(d)
  cs=[]
  for k in range(1,n+1):
   yy,xx=np.where(lab==k)
   if len(xx)>=20: cs.append((len(xx),(xx.min(),yy.min(),xx.max(),yy.max()),(round(xx.mean(),1),round(yy.mean(),1))))
  print(f+1,sorted(cs,reverse=True)[:10])
PY
python .tmp/bgseg.py"

